        <div className="text-right">
          <div className="text-sm tabular-nums text-amber">{fmtUsd(inc.impact.projected_loss_if_waiting, 0)}</div>
          <div className="font-mono text-[10px] text-faint">at risk if it waited</div>
        </div>
      )}
    </Link>
  );
}

