        {inc.impact && (
          <div className="mt-2 rounded-lg border border-line bg-white/[0.02] p-3">
            <div className="flex flex-wrap items-center gap-2">
              <Label>how Nightly priced it</Label>
              {inc.impact.economics_source && (
                <span className="ml-auto max-w-[60%] truncate font-mono text-[10.5px] text-white/40" title={inc.impact.economics_source}>
                  {inc.impact.economics_source}
                </span>
              )}
            </div>
            <div className="mt-2 font-mono text-[12px] leading-relaxed text-white/75">
              {money(inc.impact.excess_loss_per_conversation + (inc.impact.extra_llm_cost_per_conversation ?? 0), 2)} lost per bad run ×{" "}
              {inc.impact.conversations_per_minute} runs/min at {inc.impact.local_time} ={" "}
              <span className="text-amber">{money(inc.impact.loss_per_minute, 2)}/min</span>
              <br />× {inc.impact.human_response_minutes} min until a human would answer ={" "}
              <span className="text-white">{money(inc.impact.projected_loss_if_waiting)}</span> at risk
              {inc.impact.observed_loss > 0 && (
                <>
                  <br />
                  already lost before Nightly acted: <span className="text-alert">{money(inc.impact.observed_loss, 2)}</span>
                </>
              )}
            </div>
          </div>
        )}

        {/* Why it acted (or didn't) */}
        {decision?.reasons?.length ? (
          <div className="mt-3 rounded-lg border border-line p-3">
            <div className="flex flex-wrap items-center gap-2">
              <Label>why Nightly {decision.mode === "auto" ? "acted on its own" : decision.mode === "defer" ? "waited for the morning" : "asked a human"}</Label>
              {d && (
                <span className="ml-auto font-mono text-[11px] text-white/50">
                  confidence <span className="text-white">{Math.round(d.confidence * 100)}%</span> · {(d.evidence_trace_ids ?? []).length} traces cited
                </span>
              )}
            </div>
            <ul className="mt-2 space-y-1 text-[12.5px]">
              {decision.reasons.map((r, i) => {
                const last = i === decision.reasons.length - 1 && decision.mode !== "auto";
                return (
                  <li key={i} className="flex gap-2">
                    <span className={last ? "text-amber" : "text-ok"}>{last ? "!" : "✓"}</span>
                    <span className="text-white/75">{r}</span>
                  </li>
                );
              })}
            </ul>
          </div>
        ) : null}

        {/* Proposals */}
        {proposals.length > 0 && (
          <div className="mt-3 space-y-2">
            {proposals.map((a) => (
              <div key={a.id} className="flex items-start gap-3 rounded-lg border border-amber/30 bg-amber/[0.05] p-3">
                <div className="min-w-0 flex-1">
                  <Label>needs your approval · {a.kind.replaceAll("_", " ")}</Label>
                  <p className="mt-1 line-clamp-3 text-[12.5px] text-white/75">
                    {String((a.params as Record<string, unknown>).summary ?? JSON.stringify(a.params))}
                  </p>
                </div>
                <Button
                  tone="primary"
                  onClick={() =>
                    onApprove(a.id)
                      .catch((e) => alert((e as Error).message))
                      .then(onChange)
                  }
                >
                  Approve
                </Button>
              </div>
            ))}
          </div>
        )}

        {onUndo &&
          inc.actions
            .filter((a) => a.status === "applied" && a.mode === "auto")
            .map((a) => (
              <div key={a.id} className="mt-3 flex items-center gap-3 rounded-lg border border-line p-3">
                <div className="min-w-0 flex-1 text-[12.5px] text-white/75">
                  Nightly applied <span className="font-mono">{a.kind.replaceAll("_", " ")}</span> on its own. It can be undone in one step.
                </div>
                <Button tone="danger" onClick={() => onUndo(a.id).then(onChange)}>
                  Undo
                </Button>
              </div>
            ))}

        {/* Timeline */}
        <div className="mt-4">
          <Label>timeline</Label>
          <div className="mt-2 space-y-1.5 font-mono text-[11.5px]">
            {steps.map((e) => {
              const [tag, color] = KIND[e.kind] ?? [e.kind.toUpperCase(), "var(--faint)"];
              const isStep = e.kind === "step";
              return (
                <div key={e.id} className="slide-in flex gap-2">
                  <span className="shrink-0 text-white/30">{clockTime(e.ts, offset)}</span>
                  <span className="w-[78px] shrink-0" style={{ color }}>{isStep ? "  ↳ tool" : tag}</span>
                  <span className={isStep ? "text-white/45" : "text-white/85"}>{e.title}</span>
                </div>
              );
            })}
          </div>
          {thoughts.length > 0 && (
            <details className="mt-3">
              <summary className="cursor-pointer font-mono text-[11px] text-white/40">investigator reasoning ({thoughts.length})</summary>
              <div className="mt-2 space-y-2">
                {thoughts.map((t) => (
                  <p key={t.id} className="whitespace-pre-wrap text-[12px] leading-relaxed text-white/55">
                    {t.title.replace(/^think:\s*/, "")}
                  </p>
                ))}
              </div>
            </details>
          )}
        </div>
      </div>
    </div>
  );
}

